DROP TABLE IF EXISTS `learning_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `learning_records` (
  `record_id` char(36) NOT NULL,
  `user_id` char(36) NOT NULL,
  `type` enum('gap','pattern','insight') NOT NULL,
  `topic` varchar(255) NOT NULL,
  `summary` text NOT NULL,
  `recall_anchor` text,
  `first_seen_at` timestamp NOT NULL,
  `last_admitted_at` timestamp NOT NULL,
  `occurrence_count` int NOT NULL,
  `ignored_count` int NOT NULL,
  PRIMARY KEY (`record_id`),
  KEY `idx_learning_records_user_type_last` (`user_id`,`type`,`last_admitted_at`),
  CONSTRAINT `fk_learning_records_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

